steps.snippet:
day = str(int(binding["day"]))
idx = device.find(text=day)
if idx is None:
    idx = device.find(description=day)
if idx is None:
    idx = device.find(hint=day)
if idx is None:
    idx = device.find(contains=day, clickable=True)
if idx is None:
    raise RuntimeError(f"Could not find calendar day cell for {day}")
device.click(index=idx)

idx = device.find(hint="Title", editable=True)
if idx is None:
    idx = device.find(text="Title", editable=True)
if idx is None:
    raise RuntimeError("Could not find the event Title EditText")
device.input_text(binding["event_title"], index=idx)

raw_hour = ''.join(ch for ch in str(binding['hour']) if ch.isdigit())
if not raw_hour:
    raise RuntimeError("binding['hour'] is missing or not numeric")

hour = int(raw_hour)
hour_plain = str(hour)
hour_padded = f'{hour:02d}'

for desc in (f'{hour_plain} hours', f'{hour_padded} hours'):
    if device.find(description=desc, clickable=True) is not None:
        device.click(description=desc, clickable=True)
        break
else:
    for text in (hour_plain, hour_padded):
        idx = device.find(text=text, clickable=True)
        if idx is not None:
            device.click(index=idx)
            break
    else:
        raise RuntimeError(f"Could not find hour '{hour}' in the time picker")

ok_index = None
for label in ("OK", "Ok", "Okay"):
    ok_index = device.find(text=label, clickable=True)
    if ok_index is not None:
        break

if ok_index is None:
    raise LookupError("Could not find clickable OK button to confirm the selected time")

device.click(index=ok_index)

end_idx = None
for _ in range(3):
    time_idx = []
    for el in device.elements():
        text = str(el.get("text") or "")
        if (
            el.get("class_name") == "TextView"
            and el.get("clickable")
            and ":" in text
            and any(c.isdigit() for c in text)
        ):
            time_idx.append(el["index"])
    if len(time_idx) >= 2:
        end_idx = time_idx[1]
        break
    device.scroll("down")

if end_idx is None:
    raise RuntimeError("End time field not found")
device.click(index=end_idx)

idx = device.find(text="00", description="0 minutes", clickable=True)
if idx is None:
    for e in device.elements():
        if e.get("clickable") and e.get("class_name") == "View" and e.get("description", "").endswith(" minutes"):
            idx = e["index"]
            break

if idx is None:
    raise RuntimeError("Could not find the clickable minutes selector")

device.click(index=idx)

idx = device.find(hint="Title", editable=True)
if idx is None:
    idx = device.find(text="Title", editable=True)
if idx is None:
    raise ValueError("Could not find the event title input field")
device.input_text(binding["event_title"], index=idx)

idx = None
for i, el in enumerate(device.elements()):
    if (
        el.get("description") == "Delete"
        and el.get("class_name") == "FrameLayout"
        and el.get("clickable") is True
    ):
        idx = el.get("index", i)
        break

if idx is None:
    raise RuntimeError("Delete reminder control not found")

device.click(index=idx)
device.settle(0.5)

idx = None
for i, el in enumerate(device.elements()):
    if el.get("clickable") and el.get("class_name") == "TextView":
        text = (el.get("text") or "").strip()
        if ":" in text and any(ch.isdigit() for ch in text):
            idx = el.get("index", i)
            break

if idx is None:
    hour = binding.get("hour")
    if hour is not None:
        idx = device.find(text=f"{int(hour):02d}:00", clickable=True)

if idx is None:
    raise RuntimeError("Start time field not found")

device.click(index=idx)

hour_raw = binding.get("hour", binding.get("start_hour"))
if hour_raw is None:
    raise RuntimeError("binding missing hour/start_hour")

hour = int(hour_raw)
hour_texts = [str(hour), f"{hour:02d}"]
hour_descs = [f"{hour} hours", f"{hour:02d} hours"]

candidates = [
    {"text": t, "description": d, "clickable": True}
    for t in hour_texts
    for d in hour_descs
]
candidates += [
    {"description": d, "clickable": True}
    for d in hour_descs
]

idx = None
for kwargs in candidates:
    idx = device.find(**kwargs)
    if idx is not None:
        break

if idx is None:
    raise RuntimeError(f"Could not find clickable hour {hour} in the time picker")

device.click(index=idx)
device.settle(0.5)

idx = None
for e in device.elements():
    if e.get("clickable") and e.get("class_name") == "Button" and e.get("text") == "OK":
        idx = e.get("index")
        break

if idx is None:
    raise RuntimeError("Time picker OK button not found")

device.click(index=idx)
device.settle(1)

def is_time(text):
    text = (text or "").strip().upper().replace("AM", "").replace("PM", "").strip()
    parts = text.split(":")
    return len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit()

times = []
for _ in range(3):
    times = [
        e["index"]
        for e in device.elements()
        if "TextView" in (e.get("class_name") or "")
        and e.get("clickable")
        and is_time(e.get("text"))
    ]
    if len(times) >= 2:
        break
    device.scroll("down")
    device.settle(0.2)

if len(times) < 2:
    raise RuntimeError("Could not find start and end time fields")

device.click(index=times[1])
device.settle(0.5)

duration = int(str(binding["duration_mins"]).strip().split()[0])
candidates = [f"{duration} minutes", f"{duration} minute"]

if duration >= 60:
    hours, mins = divmod(duration, 60)
    hour_text = f"{hours} {'hour' if hours == 1 else 'hours'}"
    if mins:
        hour_text += f" {mins} {'minute' if mins == 1 else 'minutes'}"
    candidates.append(hour_text)

idx = None
for desc in candidates:
    idx = device.find(description=desc, clickable=True)
    if idx is not None:
        break

if idx is None:
    raise ValueError(f"No clickable duration option found for {duration} minutes")

device.click(index=idx)

app_name = binding.get("app_name", "Simple Calendar Pro")
if not app_name:
    raise ValueError("binding['app_name'] must be provided to open the calendar app")

try:
    device.open_app(app_name)
except Exception as exc:
    raise RuntimeError(f"Failed to open app '{app_name}'") from exc

device.settle(2.0)
if not device.elements():
    raise RuntimeError(f"App '{app_name}' did not load any UI elements")

idx = device.find(hint="Title", editable=True)
if idx is None:
    idx = device.find(text="Title", editable=True)
if idx is None:
    raise RuntimeError("Could not find editable Title field")

device.input_text(binding["event_title"], index=idx)

idx = device.find(hint='Description', editable=True)
if idx is None:
    idx = device.find(text='Description', editable=True)
if idx is None:
    raise RuntimeError('Could not find the Description input field')
device.input_text(binding['event_description'], index=idx)

hour = int(str(binding["hour"]).rstrip("hH"))
texts = {str(hour), f"{hour:02d}"}
descs = {f"{hour} hours", f"{hour:02d} hours"}

idx = None
for e in device.elements():
    if (
        e.get("clickable")
        and "TextView" in str(e.get("class_name", ""))
        and e.get("text") in texts
        and e.get("description") in descs
    ):
        idx = e.get("index")
        break

if idx is None:
    raise RuntimeError(f"Could not find hour {hour} in time picker")

device.click(index=idx)
